###############################################################################
# FreeLang Parser Implementation
#
# Phase 1: Minimal Lexer (Tokenization)
# Goal: Parse FreeLang source code into token stream
# Target: Match TS parser output for golden test cases
#
# Status: In Progress
# Started: 2026-03-10 17:30 UTC+9
###############################################################################

# ============================================================================
# TokenType Constants
# ============================================================================

# Keywords (40+)
fn token_type_keyword(name) {
  return "KEYWORD_" + name
}

# TokenType enum (as string constants)
let TOKEN_FN = "FN"
let TOKEN_LET = "LET"
let TOKEN_CONST = "CONST"
let TOKEN_IF = "IF"
let TOKEN_ELSE = "ELSE"
let TOKEN_FOR = "FOR"
let TOKEN_IN = "IN"
let TOKEN_WHILE = "WHILE"
let TOKEN_RETURN = "RETURN"
let TOKEN_BREAK = "BREAK"
let TOKEN_CONTINUE = "CONTINUE"
let TOKEN_MATCH = "MATCH"
let TOKEN_CASE = "CASE"
let TOKEN_ASYNC = "ASYNC"
let TOKEN_AWAIT = "AWAIT"
let TOKEN_IMPORT = "IMPORT"
let TOKEN_EXPORT = "EXPORT"
let TOKEN_FROM = "FROM"
let TOKEN_STRUCT = "STRUCT"
let TOKEN_ENUM = "ENUM"
let TOKEN_TRAIT = "TRAIT"
let TOKEN_IMPL = "IMPL"
let TOKEN_INPUT = "INPUT"
let TOKEN_OUTPUT = "OUTPUT"
let TOKEN_INTENT = "INTENT"
let TOKEN_TRY = "TRY"
let TOKEN_CATCH = "CATCH"
let TOKEN_FINALLY = "FINALLY"
let TOKEN_THROW = "THROW"
let TOKEN_TRUE = "TRUE"
let TOKEN_FALSE = "FALSE"
let TOKEN_NULL = "NULL"
let TOKEN_AS = "AS"
let TOKEN_IS = "IS"
let TOKEN_PUB = "PUB"
let TOKEN_MUT = "MUT"
let TOKEN_SELF = "SELF"
let TOKEN_SUPER = "SUPER"
let TOKEN_TYPE = "TYPE"

# Literals
let TOKEN_IDENT = "IDENT"
let TOKEN_NUMBER = "NUMBER"
let TOKEN_STRING = "STRING"
let TOKEN_CHAR = "CHAR"

# Operators
let TOKEN_PLUS = "PLUS"
let TOKEN_MINUS = "MINUS"
let TOKEN_STAR = "STAR"
let TOKEN_SLASH = "SLASH"
let TOKEN_PERCENT = "PERCENT"
let TOKEN_POWER = "POWER"

let TOKEN_EQ = "EQ"
let TOKEN_NE = "NE"
let TOKEN_LT = "LT"
let TOKEN_GT = "GT"
let TOKEN_LE = "LE"
let TOKEN_GE = "GE"

let TOKEN_AND = "AND"
let TOKEN_OR = "OR"
let TOKEN_NOT = "NOT"

let TOKEN_BIT_AND = "BIT_AND"
let TOKEN_BIT_OR = "BIT_OR"
let TOKEN_BIT_XOR = "BIT_XOR"
let TOKEN_BIT_NOT = "BIT_NOT"
let TOKEN_LSHIFT = "LSHIFT"
let TOKEN_RSHIFT = "RSHIFT"

let TOKEN_ASSIGN = "ASSIGN"
let TOKEN_PLUS_ASSIGN = "PLUS_ASSIGN"
let TOKEN_MINUS_ASSIGN = "MINUS_ASSIGN"
let TOKEN_STAR_ASSIGN = "STAR_ASSIGN"
let TOKEN_SLASH_ASSIGN = "SLASH_ASSIGN"

# Delimiters
let TOKEN_LPAREN = "LPAREN"
let TOKEN_RPAREN = "RPAREN"
let TOKEN_LBRACE = "LBRACE"
let TOKEN_RBRACE = "RBRACE"
let TOKEN_LBRACKET = "LBRACKET"
let TOKEN_RBRACKET = "RBRACKET"

let TOKEN_COLON = "COLON"
let TOKEN_SEMICOLON = "SEMICOLON"
let TOKEN_COMMA = "COMMA"
let TOKEN_DOT = "DOT"
let TOKEN_ARROW = "ARROW"
let TOKEN_FAT_ARROW = "FAT_ARROW"
let TOKEN_DOUBLE_COLON = "DOUBLE_COLON"

# Special
let TOKEN_EOF = "EOF"
let TOKEN_NEWLINE = "NEWLINE"
let TOKEN_INDENT = "INDENT"
let TOKEN_DEDENT = "DEDENT"
let TOKEN_COMMENT = "COMMENT"

# ============================================================================
# Token Data Structure
# ============================================================================

fn make_token(type, value, line, column) {
  let token = map_new()
  token["type"] = type
  token["value"] = value
  token["line"] = line
  token["column"] = column
  return token
}

fn debug_token(token) {
  println(token["type"] + " '" + (token["value"] || "") + "' @" +
          str(token["line"]) + ":" + str(token["column"]))
}

# ============================================================================
# Helper: Character Classification
# ============================================================================

fn is_whitespace(ch) {
  return ch == " " || ch == "\t" || ch == "\r" || ch == "\n"
}

fn is_newline(ch) {
  return ch == "\n" || ch == "\r"
}

fn is_digit(ch) {
  let code = str_code_at(ch, 0)
  return code >= 48 && code <= 57  # '0' = 48, '9' = 57
}

fn is_alpha(ch) {
  let code = str_code_at(ch, 0)
  return (code >= 65 && code <= 90) ||    # 'A' = 65, 'Z' = 90
         (code >= 97 && code <= 122) ||   # 'a' = 97, 'z' = 122
         ch == "_"
}

fn is_alnum(ch) {
  return is_alpha(ch) || is_digit(ch)
}

# ============================================================================
# Phase 1.1: skip_whitespace
# ============================================================================

fn skip_whitespace(src, pos, line, col) {
  let result = {
    "pos": pos,
    "line": line,
    "col": col
  }

  while pos < str_length(src) {
    let ch = str_char_at(src, pos)

    if ch == " " || ch == "\t" {
      result["pos"] = pos + 1
      result["col"] = col + 1
      pos = pos + 1
      col = col + 1

    } else if ch == "\n" {
      result["pos"] = pos + 1
      result["line"] = line + 1
      result["col"] = 1
      pos = pos + 1
      line = line + 1

    } else if ch == "\r" {
      # Handle \r or \r\n
      let next_pos = pos + 1
      if next_pos < str_length(src) && str_char_at(src, next_pos) == "\n" {
        result["pos"] = next_pos + 1
      } else {
        result["pos"] = next_pos
      }
      result["line"] = line + 1
      result["col"] = 1
      pos = result["pos"]
      line = line + 1

    } else if ch == "#" {
      # Single-line comment: skip to end of line
      while pos < str_length(src) && str_char_at(src, pos) != "\n" {
        pos = pos + 1
      }
      result["pos"] = pos
      result["col"] = col + (pos - result["pos"])

    } else {
      # Non-whitespace found
      return result
    }
  }

  return result
}

# ============================================================================
# Phase 1.2: read_identifier
# ============================================================================

fn read_identifier(src, pos) {
  let start = pos
  let value = ""

  while pos < str_length(src) {
    let ch = str_char_at(src, pos)
    if is_alnum(ch) {
      value = value + ch
      pos = pos + 1
    } else {
      break
    }
  }

  return {
    "value": value,
    "pos": pos
  }
}

fn is_keyword(word) {
  let keywords = {
    "fn": TOKEN_FN,
    "let": TOKEN_LET,
    "const": TOKEN_CONST,
    "if": TOKEN_IF,
    "else": TOKEN_ELSE,
    "for": TOKEN_FOR,
    "in": TOKEN_IN,
    "while": TOKEN_WHILE,
    "return": TOKEN_RETURN,
    "break": TOKEN_BREAK,
    "continue": TOKEN_CONTINUE,
    "match": TOKEN_MATCH,
    "case": TOKEN_CASE,
    "async": TOKEN_ASYNC,
    "await": TOKEN_AWAIT,
    "import": TOKEN_IMPORT,
    "export": TOKEN_EXPORT,
    "from": TOKEN_FROM,
    "struct": TOKEN_STRUCT,
    "enum": TOKEN_ENUM,
    "trait": TOKEN_TRAIT,
    "impl": TOKEN_IMPL,
    "input": TOKEN_INPUT,
    "output": TOKEN_OUTPUT,
    "intent": TOKEN_INTENT,
    "try": TOKEN_TRY,
    "catch": TOKEN_CATCH,
    "finally": TOKEN_FINALLY,
    "throw": TOKEN_THROW,
    "true": TOKEN_TRUE,
    "false": TOKEN_FALSE,
    "null": TOKEN_NULL,
    "as": TOKEN_AS,
    "is": TOKEN_IS,
    "pub": TOKEN_PUB,
    "mut": TOKEN_MUT,
    "self": TOKEN_SELF,
    "super": TOKEN_SUPER,
    "type": TOKEN_TYPE
  }

  if word in keywords {
    return keywords[word]
  }
  return null
}

# ============================================================================
# Phase 1.3: read_number
# ============================================================================

fn read_number(src, pos) {
  let start = pos
  let value = ""

  # Integer part
  while pos < str_length(src) {
    let ch = str_char_at(src, pos)
    if is_digit(ch) {
      value = value + ch
      pos = pos + 1
    } else {
      break
    }
  }

  # Decimal part (if any)
  if pos < str_length(src) && str_char_at(src, pos) == "." {
    let next_pos = pos + 1
    if next_pos < str_length(src) && is_digit(str_char_at(src, next_pos)) {
      value = value + "."
      pos = next_pos
      while pos < str_length(src) {
        let ch = str_char_at(src, pos)
        if is_digit(ch) {
          value = value + ch
          pos = pos + 1
        } else {
          break
        }
      }
    }
  }

  return {
    "value": value,
    "pos": pos
  }
}

# ============================================================================
# Phase 1.4: read_string
# ============================================================================

fn read_string(src, pos, quote_char) {
  let value = ""
  pos = pos + 1  # Skip opening quote

  while pos < str_length(src) {
    let ch = str_char_at(src, pos)

    if ch == quote_char {
      # End of string
      pos = pos + 1
      return {
        "value": value,
        "pos": pos,
        "error": null
      }
    } else if ch == "\\" {
      # Escape sequence
      pos = pos + 1
      if pos < str_length(src) {
        let next_ch = str_char_at(src, pos)
        if next_ch == "n" {
          value = value + "\n"
        } else if next_ch == "t" {
          value = value + "\t"
        } else if next_ch == "r" {
          value = value + "\r"
        } else if next_ch == "\\" {
          value = value + "\\"
        } else if next_ch == quote_char {
          value = value + quote_char
        } else {
          value = value + next_ch
        }
        pos = pos + 1
      }
    } else {
      value = value + ch
      pos = pos + 1
    }
  }

  return {
    "value": value,
    "pos": pos,
    "error": "Unterminated string"
  }
}

# ============================================================================
# Phase 1.5: Main Tokenizer
# ============================================================================

fn tokenize(src) {
  let tokens = []
  let pos = 0
  let line = 1
  let col = 1

  while pos < str_length(src) {
    # Skip whitespace
    let skip_result = skip_whitespace(src, pos, line, col)
    pos = skip_result["pos"]
    line = skip_result["line"]
    col = skip_result["col"]

    if pos >= str_length(src) {
      break
    }

    let ch = str_char_at(src, pos)

    # Identifiers and keywords
    if is_alpha(ch) {
      let ident_result = read_identifier(src, pos)
      let value = ident_result["value"]
      let token_type = is_keyword(value)
      if token_type == null {
        token_type = TOKEN_IDENT
      }
      tokens = append(tokens, make_token(token_type, value, line, col))
      pos = ident_result["pos"]
      col = col + str_length(value)

    # Numbers
    } else if is_digit(ch) {
      let num_result = read_number(src, pos)
      tokens = append(tokens, make_token(TOKEN_NUMBER, num_result["value"], line, col))
      pos = num_result["pos"]
      col = col + str_length(num_result["value"])

    # Strings
    } else if ch == "\"" || ch == "'" {
      let str_result = read_string(src, pos, ch)
      if str_result["error"] != null {
        # TODO: Better error handling
        tokens = append(tokens, make_token("ERROR", str_result["error"], line, col))
      } else {
        tokens = append(tokens, make_token(TOKEN_STRING, str_result["value"], line, col))
      }
      pos = str_result["pos"]
      col = col + (pos - (col - 1))

    # Two-character operators
    } else if pos + 1 < str_length(src) {
      let ch2 = str_char_at(src, pos + 1)
      let two_char = ch + ch2

      if two_char == "==" {
        tokens = append(tokens, make_token(TOKEN_EQ, "==", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "!=" {
        tokens = append(tokens, make_token(TOKEN_NE, "!=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "<=" {
        tokens = append(tokens, make_token(TOKEN_LE, "<=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == ">=" {
        tokens = append(tokens, make_token(TOKEN_GE, ">=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "&&" {
        tokens = append(tokens, make_token(TOKEN_AND, "&&", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "||" {
        tokens = append(tokens, make_token(TOKEN_OR, "||", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "**" {
        tokens = append(tokens, make_token(TOKEN_POWER, "**", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "+=" {
        tokens = append(tokens, make_token(TOKEN_PLUS_ASSIGN, "+=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "-=" {
        tokens = append(tokens, make_token(TOKEN_MINUS_ASSIGN, "-=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "*=" {
        tokens = append(tokens, make_token(TOKEN_STAR_ASSIGN, "*=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "/=" {
        tokens = append(tokens, make_token(TOKEN_SLASH_ASSIGN, "/=", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "->" {
        tokens = append(tokens, make_token(TOKEN_ARROW, "->", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "=>" {
        tokens = append(tokens, make_token(TOKEN_FAT_ARROW, "=>", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "::" {
        tokens = append(tokens, make_token(TOKEN_DOUBLE_COLON, "::", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == "<<" {
        tokens = append(tokens, make_token(TOKEN_LSHIFT, "<<", line, col))
        pos = pos + 2
        col = col + 2
      } else if two_char == ">>" {
        tokens = append(tokens, make_token(TOKEN_RSHIFT, ">>", line, col))
        pos = pos + 2
        col = col + 2
      } else {
        # Single-character operators
        goto single_char
      }

    } else {
      single_char:
      # Single-character operators
      if ch == "+" {
        tokens = append(tokens, make_token(TOKEN_PLUS, "+", line, col))
      } else if ch == "-" {
        tokens = append(tokens, make_token(TOKEN_MINUS, "-", line, col))
      } else if ch == "*" {
        tokens = append(tokens, make_token(TOKEN_STAR, "*", line, col))
      } else if ch == "/" {
        tokens = append(tokens, make_token(TOKEN_SLASH, "/", line, col))
      } else if ch == "%" {
        tokens = append(tokens, make_token(TOKEN_PERCENT, "%", line, col))
      } else if ch == "=" {
        tokens = append(tokens, make_token(TOKEN_ASSIGN, "=", line, col))
      } else if ch == "<" {
        tokens = append(tokens, make_token(TOKEN_LT, "<", line, col))
      } else if ch == ">" {
        tokens = append(tokens, make_token(TOKEN_GT, ">", line, col))
      } else if ch == "!" {
        tokens = append(tokens, make_token(TOKEN_NOT, "!", line, col))
      } else if ch == "&" {
        tokens = append(tokens, make_token(TOKEN_BIT_AND, "&", line, col))
      } else if ch == "|" {
        tokens = append(tokens, make_token(TOKEN_BIT_OR, "|", line, col))
      } else if ch == "^" {
        tokens = append(tokens, make_token(TOKEN_BIT_XOR, "^", line, col))
      } else if ch == "~" {
        tokens = append(tokens, make_token(TOKEN_BIT_NOT, "~", line, col))
      } else if ch == "(" {
        tokens = append(tokens, make_token(TOKEN_LPAREN, "(", line, col))
      } else if ch == ")" {
        tokens = append(tokens, make_token(TOKEN_RPAREN, ")", line, col))
      } else if ch == "{" {
        tokens = append(tokens, make_token(TOKEN_LBRACE, "{", line, col))
      } else if ch == "}" {
        tokens = append(tokens, make_token(TOKEN_RBRACE, "}", line, col))
      } else if ch == "[" {
        tokens = append(tokens, make_token(TOKEN_LBRACKET, "[", line, col))
      } else if ch == "]" {
        tokens = append(tokens, make_token(TOKEN_RBRACKET, "]", line, col))
      } else if ch == ":" {
        tokens = append(tokens, make_token(TOKEN_COLON, ":", line, col))
      } else if ch == ";" {
        tokens = append(tokens, make_token(TOKEN_SEMICOLON, ";", line, col))
      } else if ch == "," {
        tokens = append(tokens, make_token(TOKEN_COMMA, ",", line, col))
      } else if ch == "." {
        tokens = append(tokens, make_token(TOKEN_DOT, ".", line, col))
      } else {
        # Unknown character
        tokens = append(tokens, make_token("UNKNOWN", ch, line, col))
      }

      pos = pos + 1
      col = col + 1
    }
  }

  # Add EOF token
  tokens = append(tokens, make_token(TOKEN_EOF, "", line, col))
  return tokens
}

