fn is_newline(ch) {
  return ch == "\n" || ch == "\r"
}

fn is_digit(ch) {
  let code = char_code(ch)
  return code >= 48 && code <= 57  # '0' = 48, '9' = 57
}

fn is_alpha(ch) {
  let code = char_code(ch)
  return (code >= 65 && code <= 90) ||    # 'A' = 65, 'Z' = 90
         (code >= 97 && code <= 122) ||   # 'a' = 97, 'z' = 122
         ch == "_"
}

fn is_alnum(ch) {
  return is_alpha(ch) || is_digit(ch)
}

# ============================================================================
# Phase 1.1: skip_whitespace
# ============================================================================

fn skip_whitespace(src, pos, line, col) {
  let result = map_new()
  result["pos"] = pos
  result["line"] = line
  result["col"] = col

  while pos < strlen(src) {
    let ch = str_at(src, pos)

    if ch == " " || ch == "\t" {
      result["pos"] = pos + 1
      result["col"] = col + 1
      pos = pos + 1
      col = col + 1

    } else if ch == "\n" {
      result["pos"] = pos + 1
      result["line"] = line + 1
      result["col"] = 1
      pos = pos + 1
      line = line + 1

    } else if ch == "\r" {
      # Handle \r or \r\n
      let next_pos = pos + 1
      if next_pos < strlen(src) && str_at(src, next_pos) == "\n" {
        result["pos"] = next_pos + 1
      } else {
        result["pos"] = next_pos
      }
      result["line"] = line + 1
      result["col"] = 1
      pos = result["pos"]
      line = line + 1

    } else if ch == "#" {
      # Single-line comment: skip to end of line
      while pos < strlen(src) && str_at(src, pos) != "\n" {
        pos = pos + 1
      }
      result["pos"] = pos
      result["col"] = col + (pos - result["pos"])

    } else {
      # Non-whitespace found
      return result
    }
  }

  return result
}

