# ============================================================================
# Helper: Character Classification
# ============================================================================

fn is_whitespace(ch) {
  return ch == " " || ch == "\t" || ch == "\r" || ch == "\n"
}

fn is_newline(ch) {
  return ch == "\n" || ch == "\r"
}

fn is_digit(ch) {
  # '0' = 48, '9' = 57 (char codes)
  return ch == "0" || ch == "1" || ch == "2" || ch == "3" || ch == "4" ||
         ch == "5" || ch == "6" || ch == "7" || ch == "8" || ch == "9"
}

fn is_alpha(ch) {
  # Check a-z, A-Z, or _
  return (ch >= "a" && ch <= "z") ||
         (ch >= "A" && ch <= "Z") ||
         ch == "_"
}

fn is_alnum(ch) {
  return is_alpha(ch) || is_digit(ch)
}

# ============================================================================
# Phase 1.1: skip_whitespace
# ============================================================================

fn skip_whitespace(src, pos, line, col) {
  let result = map_new()
  result["pos"] = pos
  result["line"] = line
  result["col"] = col

  while pos < strlen(src) {
    let ch = str_char_at(src, pos)

    if ch == " " || ch == "\t" {
      result["pos"] = pos + 1
      result["col"] = col + 1
      pos = pos + 1
      col = col + 1

    } else if ch == "\n" {
      result["pos"] = pos + 1
      result["line"] = line + 1
      result["col"] = 1
      pos = pos + 1
      line = line + 1

    } else if ch == "\r" {
      # Handle \r or \r\n
      let next_pos = pos + 1
      if next_pos < strlen(src) && str_char_at(src, next_pos) == "\n" {
        result["pos"] = next_pos + 1
      } else {
        result["pos"] = next_pos
      }
      result["line"] = line + 1
      result["col"] = 1
      pos = result["pos"]
      line = line + 1

    } else if ch == "#" {
      # Single-line comment: skip to end of line
      while pos < strlen(src) && str_char_at(src, pos) != "\n" {
        pos = pos + 1
      }
      result["pos"] = pos
      result["col"] = col + (pos - result["pos"])

    } else {
      # Non-whitespace found
      return result
    }
  }

  return result
}

# ============================================================================
# Phase 1.2: read_identifier
# ============================================================================

fn read_identifier(src, pos) {
  let value = ""

  while pos < strlen(src) {
    let ch = str_char_at(src, pos)
    if is_alnum(ch) {
      value = value + ch
      pos = pos + 1
    } else {
      break
    }
  }

  return {
    "value": value,
    "pos": pos
  }
}

