import { Token, TokenType, getKeyword } from './token';

/**
 * Lexer - Tokenizes FreeLang source code
 */
export class Lexer {
  private input: string;
  private position: number = 0;
  private line: number = 1;
  private column: number = 0;
  private current: string = '';
  private lastTokenType: TokenType = TokenType.EOF;  // Track last token for regex disambiguation

  constructor(input: string) {
    this.input = input;
    this.readChar();
  }

  /**
   * Read next character
   */
  private readChar(): void {
    if (this.position >= this.input.length) {
      this.current = '\0';
    } else {
      this.current = this.input[this.position];
    }
    this.position++;
    this.column++;
  }

  /**
   * Peek at next character without consuming
   */
  private peekChar(): string {
    if (this.position >= this.input.length) {
      return '\0';
    }
    return this.input[this.position];
  }

  /**
   * Skip whitespace
   */
  private skipWhitespace(): void {
    while (this.current === ' ' || this.current === '\t' || this.current === '\r') {
      this.readChar();
    }
  }

  /**
   * Skip single-line comment
   */
  private skipComment(): void {
    // Skip //
    this.readChar();
    this.readChar();

    // Read until newline
    while (this.current !== '\n' && this.current !== '\0') {
      this.readChar();
    }
  }

  /**
   * Skip multi-line comment
   */
  private skipMultiLineComment(): void {
    // Skip /*
    this.readChar();
    this.readChar();

    while (true) {
      if (this.current === '\0') {
        break;
      }

      if (this.current === '\n') {
        this.line++;
        this.column = 0;
      }

      if (this.current === '*' && this.peekChar() === '/') {
        this.readChar(); // *
        this.readChar(); // /
        break;
      }

      this.readChar();
    }
  }

