input.content:
/**
 * Phase 1 Lexer Validation Tool
 * Analyzes TS lexer baseline and prepares parser.fl validation
 *
 * This tool:
 * 1. Reads baseline JSON files from TS lexer
 * 2. Generates detailed token analysis reports
 * 3. Creates validation checklist for parser.fl
 * 4. Documents expected vs actual token sequences
 */

import fs from 'fs';
import path from 'path';

interface TokenInfo {
  index: number;
  type: string;
  value: string;
  position: string;
}

interface BaselineData {
  total: number;
  tokens: TokenInfo[];
}

interface ValidationReport {
  filename: string;
  total: number;
  tokens: TokenInfo[];
  keyTokens: string[];
  analysis: string;
}

/**
 * Read baseline JSON file
 */
function readBaseline(filename: string): BaselineData {
  const filepath = path.join(__dirname, 'tests', 'parser-golden', filename);
  const content = fs.readFileSync(filepath, 'utf-8');
  return JSON.parse(content);
}

/**
 * Extract key token types for quick verification
 */
function extractKeyTokens(tokens: TokenInfo[]): string[] {
  const keyTypes: string[] = [];
  let typeCount: { [key: string]: number } = {};

  for (const token of tokens) {
    if (!typeCount[token.type]) {
      typeCount[token.type] = 0;
    }
    typeCount[token.type]++;
  }

  // Get top 10 token types by frequency
  const sorted = Object.entries(typeCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10);

  return sorted.map(([type, count]) => `${type}(${count})`);
}

/**
 * Generate detailed analysis for a file
 */
function analyzeBaseline(filename: string): ValidationReport {
  const baseline = readBaseline(filename + '.tokens-ts.json');
  const keyTokens = extractKeyTokens(baseline.tokens);

  // Generate analysis text
  let analysis = `File: ${filename}\n`;
  analysis += `Total tokens: ${baseline.total}\n`;
  analysis += `Token types: ${keyTokens.join(', ')}\n`;

  // First 5 tokens
  analysis += `\nFirst 5 tokens:\n`;
  for (let i = 0; i < Math.min(5, baseline.tokens.length); i++) {
    const t = baseline.tokens[i];
    const val = t.value ? `"${t.value}"` : '(empty)';
    analysis += `  ${i + 1}. ${t.type} = ${val}\n`;
  }

  // Last 5 tokens
  const lastStart = Math.max(0, baseline.tokens.length - 5);
  if (lastStart > 5) {
    analysis += `\nLast 5 tokens:\n`;
    for (let i = lastStart; i < baseline.tokens.length; i++) {
      const t = baseline.tokens[i];
      const val = t.value ? `"${t.value}"` : '(empty)';
      analysis += `  ${i + 1}. ${t.type} = ${val}\n`;
    }
  }

  return {
    filename,
    total: baseline.total,
    tokens: baseline.tokens,
    keyTokens,
    analysis
  };
}

/**
 * Main validation report
 */
function main() {
  console.log('╔' + '═'.repeat(70) + '╗');
  console.log('║ 🧪 Phase 1 Lexer Baseline Analysis & Validation Checklist'.padEnd(71) + '║');
  console.log('╚' + '═'.repeat(70) + '╝');
  console.log('');

  const testFiles = [
    'hello.fl',
    'arithmetic.fl',
    'conditions.fl',
    'loops.fl',
    'functions.fl'
  ];

  const allReports: ValidationReport[] = [];
  let totalTokens = 0;

  // Analyze each file
  for (const file of testFiles) {
    const report = analyzeBaseline(file);
    allReports.push(report);
    totalTokens += report.total;

    console.log(`\n📄 ${file.toUpperCase()}`);
    console.log('─'.repeat(70));
    console.log(report.analysis);
  }

  // Summary
  console.log('\n╔' + '═'.repeat(70) + '╗');
  console.log('║ 📊 PHASE 1 BASELINE SUMMARY'.padEnd(71) + '║');
  console.log('╚' + '═'.repeat(70) + '╝');
  console.log('');

  console.log('File Summary:');
  console.log('┌─────────────────┬────────┬──────────────┐');
  console.log('│ File            │ Tokens │ Key Types    │');
  console.log('├─────────────────┼────────┼──────────────┤');

  for (const report of allReports) {
    const tokenStr = report.total.toString().padStart(6);
    const typesStr = report.keyTokens.slice(0, 3).join(', ');
    const filename = report.filename.padEnd(15);
    console.log(`│ ${filename} │${tokenStr} │ ${typesStr.padEnd(12)}│`);
  }

  console.log('└─────────────────┴────────┴──────────────┘');
  console.log('');
  console.log(`Total Files:   ${testFiles.length}`);
  console.log(`Total Tokens:  ${totalTokens}`);
  console.log(`Avg/File:      ${(totalTokens / testFiles.length).toFixed(1)}`);

  // Validation checklist
  console.log('\n╔' + '═'.repeat(70) + '╗');
  console.log('║ ✅ VALIDATION CHECKLIST FOR parser.fl'.padEnd(71) + '║');
  console.log('╚' + '═'.repeat(70) + '╝');
  console.log('');

  console.log('Run the following tests to validate parser.fl:');
  console.log('');

  let checkNum = 1;
  for (const report of allReports) {
    console.log(`${checkNum}. ${report.filename}`);
    console.log(`   □ Token count: ${report.total}`);
    console.log(`   □ First token type: ${report.tokens[0]?.type}`);
    console.log(`   □ Last token type: ${report.tokens[report.tokens.length - 1]?.type}`);
    console.log('');
    checkNum++;
  }

  // Expected vs Actual template
  console.log('Comparison Template (Save to validation-results.txt):');
  console.log('');
  console.log('EXPECTED (TS Baseline):');
  for (const report of allReports) {
    console.log(`  ${report.filename}: ${report.total} tokens`);
  }
  console.log('');
  console.log('ACTUAL (parser.fl tokenize):');
  for (const report of allReports) {
    console.log(`  ${report.filename}: ____ tokens (run test-parser-validation.fl)`);
  }
  console.log('');

  console.log('═'.repeat(70));
  console.log('✅ Baseline analysis complete!');
  console.log('');
  console.log('Next step: Run test-parser-validation.fl in FreeLang');
  console.log('Then compare actual token counts against the checklist above');
  console.log('');
}

main();

