# ============================================================================

fn read_string(src, pos, quote_char) {
  let value = ""
  pos = pos + 1  # Skip opening quote

  while pos < strlen(src) {
    let ch = str_char_at(src, pos)

    if ch == quote_char {
      # End of string
      pos = pos + 1
      let result = map_new()
      result["value"] = value
      result["pos"] = pos
      result["error"] = null
      return result
    } else if ch == "\\" {
      # Escape sequence
      pos = pos + 1
      if pos < strlen(src) {
        let next_ch = str_char_at(src, pos)
        if next_ch == "n" {
          value = value + "\n"
        } else if next_ch == "t" {
          value = value + "\t"
        } else if next_ch == "r" {
          value = value + "\r"
        } else if next_ch == "\\" {
          value = value + "\\"
        } else if next_ch == quote_char {
          value = value + quote_char
        } else {
          value = value + next_ch
        }
        pos = pos + 1
      }
    } else {
      value = value + ch
      pos = pos + 1
    }
  }

